_ANIMALS = ["fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"]

_COMMENTS = {
    "fly": None,
    "spider": "It wriggled and jiggled and tickled inside her.",
    "bird": "How absurd to swallow a bird!",
    "cat": "Imagine that, to swallow a cat!",
    "dog": "What a hog, to swallow a dog!",
    "goat": "Just opened her throat and swallowed a goat!",
    "cow": "I don't know how she swallowed a cow!",
    "horse": "She's dead, of course!",
}


def _catch_phrase(caught):
    if caught == "spider":
        return "the spider that wriggled and jiggled and tickled inside her"
    return f"the {caught}"


def _recite(verse):
    animal = _ANIMALS[verse - 1]
    lines = [f"I know an old lady who swallowed a {animal}."]
    comment = _COMMENTS[animal]
    if comment:
        lines.append(comment)
    if animal == "horse":
        return lines

    for caught in reversed(_ANIMALS[: verse - 1]):
        lines.append(
            f"She swallowed the {animal} to catch {_catch_phrase(caught)}."
        )
        animal = caught
    lines.append("I don't know why she swallowed the fly. Perhaps she'll die.")
    return lines


def recite(start_verse, end_verse):
    lines = []
    for verse in range(start_verse, end_verse + 1):
        if lines:
            lines.append("")
        lines.extend(_recite(verse))
    return lines

